package com.taxirank.backend.storage;

import java.util.Optional;

/**
 * Where profile photos live. Local disk for now; an S3 implementation replaces it on
 * AWS without touching callers. Keys are opaque and generated by the storage.
 */
public interface PhotoStorage {
    /** Stores a processed JPEG and returns its key */
    String save(byte[] jpeg);

    Optional<byte[]> load(String key);

    /** Does nothing if the key doesn't exist */
    void delete(String key);
}
